import java.io.*;

public class Main {
    static class FrequencyTracker {
        FrequencyTracker() {
            // Write your solution here
        }
        void add(long x) {}
        void remove(long x) {}
        long getMin() { return -1; }
        long getMax() { return -1; }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        FrequencyTracker tracker = new FrequencyTracker();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            String op = st.nextToken();
            if (op.equals("add")) tracker.add(Long.parseLong(st.nextToken()));
            else if (op.equals("remove")) tracker.remove(Long.parseLong(st.nextToken()));
            else if (op.equals("min")) sb.append(tracker.getMin()).append("\n");
            else sb.append(tracker.getMax()).append("\n");
        }
        System.out.print(sb);
    }
}

