def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    tests = [
        fmt(['min']),
        fmt(['max']),
        fmt(['remove 5', 'max', 'min']),
        fmt(['add 1000000000', 'min', 'max', 'remove 1000000000', 'min']),
        fmt(['add 3', 'add 2', 'add 1', 'min', 'max']),
    ]
    for _ in range(50):
        q = rng.randint(2, 40)
        hi = rng.choice([2, 3, 5, 8])
        ops = []
        for _ in range(q):
            t = rng.random()
            if t < 0.35:
                ops.append('add %d' % rng.randint(1, hi))
            elif t < 0.55:
                ops.append('remove %d' % rng.randint(1, hi))
            elif t < 0.78:
                ops.append('min')
            else:
                ops.append('max')
        ops.append(rng.choice(['min', 'max']))
        tests.append(fmt(ops))
    q = 10**5
    # many distinct elements, alternating queries
    ops = []
    for i in range(q // 2):
        if i % 2 == 0:
            ops.append('add %d' % rng.randint(1, 10**9))
        else:
            ops.append(rng.choice(['min', 'max']))
    ops.append('max')
    tests.append(fmt(ops[:q]))
    # build 40000 distinct elements, then churn
    ops = ['add %d' % (i + 1) for i in range(40000)]
    live = list(range(1, 40001))
    while len(ops) < q - 1:
        t = rng.random()
        if t < 0.3:
            ops.append('add %d' % rng.choice(live))
        elif t < 0.45:
            ops.append('remove %d' % rng.choice(live))
        elif t < 0.725:
            ops.append('min')
        else:
            ops.append('max')
    ops.append('min')
    tests.append(fmt(ops))
    # small value range, heavy churn
    ops = []
    for _ in range(q - 1):
        t = rng.random()
        if t < 0.35:
            ops.append('add %d' % rng.randint(1, 300))
        elif t < 0.6:
            ops.append('remove %d' % rng.randint(1, 300))
        elif t < 0.8:
            ops.append('min')
        else:
            ops.append('max')
    ops.append('max')
    tests.append(fmt(ops))
    # staircase: element i added i times, then queries while removing
    ops = []
    for i in range(1, 440):
        ops.extend(['add %d' % i] * i)
    ops = ops[:60000]
    for i in range(1, 440):
        if len(ops) >= q - 2:
            break
        ops.append('min')
        ops.append('remove %d' % rng.randint(1, 439))
        ops.append('max')
    ops = ops[:q - 1]
    ops.append('max')
    tests.append(fmt(ops))
    return tests
